import React, { useState, useEffect, useRef } from 'react';
import { 
  BarChart3, 
  TrendingUp, 
  Download, 
  Filter, 
  MoreVertical,
  Target,
  DollarSign,
  TrendingDown,
  Sparkles,
  Calendar,
  ChevronDown
} from 'lucide-react';

const RevenueChart = () => {
  const [timeRange, setTimeRange] = useState('Mois');
  const [isLoading, setIsLoading] = useState(true);
  const [hoveredBar, setHoveredBar] = useState(null);
  const [isFilterOpen, setIsFilterOpen] = useState(false);
  const chartRef = useRef(null);

  useEffect(() => {
    const timer = setTimeout(() => setIsLoading(false), 1200);
    return () => clearTimeout(timer);
  }, []);

  const timeRanges = [
    { id: 'jour', label: 'Jour', icon: '📊' },
    { id: 'semaine', label: 'Semaine', icon: '📈' },
    { id: 'mois', label: 'Mois', icon: '💰' },
    { id: 'annee', label: 'Année', icon: '🎯' }
  ];

  const monthlyData = [
    { month: 'Jan', revenue: 12000, growth: 15, target: 18000 },
    { month: 'Fév', revenue: 19000, growth: 25, target: 17000 },
    { month: 'Mar', revenue: 15000, growth: 8, target: 16000 },
    { month: 'Avr', revenue: 22000, growth: 32, target: 20000 },
    { month: 'Mai', revenue: 28000, growth: 45, target: 25000 },
    { month: 'Jun', revenue: 32000, growth: 52, target: 28000 },
    { month: 'Jul', revenue: 38000, growth: 68, target: 32000 },
    { month: 'Aoû', revenue: 42000, growth: 75, target: 38000 },
  ];

  const maxRevenue = Math.max(...monthlyData.map(d => d.revenue));
  const maxTarget = Math.max(...monthlyData.map(d => d.target));
  const maxValue = Math.max(maxRevenue, maxTarget);

  // Calcul des statistiques
  const totalRevenue = monthlyData.reduce((sum, d) => sum + d.revenue, 0);
  const averageRevenue = Math.round(totalRevenue / monthlyData.length);
  const averageGrowth = Math.round(monthlyData.reduce((sum, d) => sum + d.growth, 0) / monthlyData.length);
  const targetAchievement = Math.round((totalRevenue / monthlyData.reduce((sum, d) => sum + d.target, 0)) * 100);
  const highestGrowth = Math.max(...monthlyData.map(d => d.growth));

  const getBarColor = (growth) => {
    if (growth >= 40) return 'from-emerald-500 to-emerald-400';
    if (growth >= 20) return 'from-blue-500 to-blue-400';
    if (growth >= 0) return 'from-primary-500 to-primary-400';
    return 'from-amber-500 to-amber-400';
  };

  const getGrowthColor = (growth) => {
    if (growth >= 40) return 'text-emerald-600 dark:text-emerald-400';
    if (growth >= 20) return 'text-blue-600 dark:text-blue-400';
    if (growth >= 0) return 'text-primary-600 dark:text-primary-400';
    return 'text-amber-600 dark:text-amber-400';
  };

  const handleDownload = () => {
    console.log('Exporting chart data...');
    // Implémenter la logique d'export ici
  };

  return (
    <div className="relative bg-white/80 dark:bg-neutral-900/80 backdrop-blur-xl 
      rounded-2xl p-6 sm:p-8 shadow-xl border border-white/40 dark:border-neutral-800/50 
      hover:shadow-2xl hover:shadow-primary-500/10 dark:hover:shadow-black/30 
      transition-all duration-500 animate-fade-in group"
      ref={chartRef}
    >
      {/* Effet de particules subtiles */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 right-0 w-32 h-32 bg-primary-500/5 rounded-full blur-3xl" />
        <div className="absolute bottom-0 left-0 w-48 h-48 bg-accent-500/5 rounded-full blur-3xl" />
      </div>

      {/* En-tête avec contrôles */}
      <div className="relative z-10">
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 mb-8">
          <div className="space-y-2">
            <div className="flex items-center gap-3">
              <div className="p-2.5 bg-primary-500/10 dark:bg-primary-500/20 rounded-xl">
                <BarChart3 className="h-6 w-6 text-primary-600 dark:text-primary-400 animate-pulse-gentle" />
              </div>
              <div>
                <h3 className="text-xl sm:text-2xl font-bold text-neutral-900 dark:text-white">
                  Analyse des revenus
                </h3>
                <div className="flex items-center gap-2 mt-1">
                  <TrendingUp className="h-4 w-4 text-accent-600 dark:text-accent-400" />
                  <p className="text-sm text-neutral-600 dark:text-neutral-400">
                    Performance financière en temps réel
                  </p>
                </div>
              </div>
            </div>
          </div>

          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
            {/* Sélecteur de plage de temps */}
            <div className="relative">
              <div className="flex bg-neutral-100/50 dark:bg-neutral-800/50 backdrop-blur-sm 
                rounded-xl p-1 border border-neutral-200/50 dark:border-neutral-700/50">
                {timeRanges.map((range) => (
                  <button
                    key={range.id}
                    onClick={() => setTimeRange(range.label)}
                    className={`flex items-center gap-2 px-4 py-2.5 text-sm rounded-lg transition-all duration-300 ${
                      timeRange === range.label
                        ? 'bg-white dark:bg-neutral-700 text-primary-600 dark:text-primary-400 font-semibold shadow-lg'
                        : 'text-neutral-600 dark:text-neutral-400 hover:text-neutral-900 dark:hover:text-white hover:bg-white/50 dark:hover:bg-neutral-700/50'
                    }`}
                  >
                    <span>{range.icon}</span>
                    <span>{range.label}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Boutons d'action */}
            <div className="flex items-center gap-2">
              <div className="relative">
                <button
                  onClick={() => setIsFilterOpen(!isFilterOpen)}
                  className="p-2.5 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl 
                    transition-all duration-300 border border-neutral-200/50 dark:border-neutral-700/50
                    hover:scale-105 active:scale-95"
                  aria-label="Filtres"
                >
                  <Filter className="h-5 w-5 text-neutral-600 dark:text-neutral-400" />
                </button>

                {isFilterOpen && (
                  <div className="absolute top-full right-0 mt-2 w-48 bg-white dark:bg-neutral-800 
                    rounded-xl shadow-2xl border border-neutral-200 dark:border-neutral-700 
                    py-2 z-50 animate-scale-in">
                    <div className="px-4 py-2 text-sm font-semibold text-neutral-900 dark:text-white">
                      Filtres avancés
                    </div>
                    <div className="px-4 py-1 text-sm text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-700 cursor-pointer">
                      Par catégorie
                    </div>
                    <div className="px-4 py-1 text-sm text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-700 cursor-pointer">
                      Par région
                    </div>
                    <div className="px-4 py-1 text-sm text-neutral-600 dark:text-neutral-400 hover:bg-neutral-100 dark:hover:bg-neutral-700 cursor-pointer">
                      Par produit
                    </div>
                  </div>
                )}
              </div>

              <button
                onClick={handleDownload}
                className="p-2.5 hover:bg-neutral-100 dark:hover:bg-neutral-800 rounded-xl 
                  transition-all duration-300 border border-neutral-200/50 dark:border-neutral-700/50
                  hover:scale-105 active:scale-95 group/download"
                aria-label="Télécharger le rapport"
              >
                <Download className="h-5 w-5 text-neutral-600 dark:text-neutral-400 
                  group-hover/download:text-primary-600 dark:group-hover/download:text-primary-400 
                  transition-colors" />
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Contenu principal */}
      <div className="relative z-10">
        {isLoading ? (
          <div className="h-[400px] flex flex-col items-center justify-center">
            <div className="relative">
              <div className="w-16 h-16 border-4 border-primary-500/20 rounded-full" />
              <div className="absolute inset-0 w-16 h-16 border-4 border-primary-500 
                border-t-transparent rounded-full animate-spin" />
              <Sparkles className="absolute -top-2 -right-2 h-6 w-6 text-accent-500 
                animate-pulse" />
            </div>
            <p className="mt-4 text-sm font-medium text-neutral-600 dark:text-neutral-400">
              Analyse des données en cours...
            </p>
            <p className="text-xs text-neutral-500 dark:text-neutral-500 mt-2">
              Chargement des performances financières
            </p>
          </div>
        ) : (
          <>
            {/* Légende */}
            <div className="flex flex-wrap items-center justify-between gap-4 mb-6 p-4 
              bg-neutral-50/50 dark:bg-neutral-800/30 rounded-xl backdrop-blur-sm">
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-gradient-to-r from-primary-500 to-primary-400 rounded-full" />
                  <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
                    Revenus réels
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-gradient-to-r from-accent-500 to-accent-400 rounded-full" />
                  <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
                    Objectifs
                  </span>
                </div>
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-gradient-to-r from-emerald-500 to-emerald-400 rounded-full" />
                  <span className="text-sm font-medium text-neutral-700 dark:text-neutral-300">
                    Croissance
                  </span>
                </div>
              </div>

              <div className="flex items-center gap-2 px-3 py-1.5 bg-white dark:bg-neutral-800 
                rounded-lg border border-neutral-200 dark:border-neutral-700">
                <Calendar className="h-4 w-4 text-neutral-500" />
                <span className="text-sm text-neutral-600 dark:text-neutral-400">
                  Dernière mise à jour : Aujourd'hui
                </span>
              </div>
            </div>

            {/* Graphique à barres */}
            <div className="relative h-72 mb-8">
              {/* Grille de fond */}
              <div className="absolute inset-0 flex flex-col justify-between">
                {[0, 20, 40, 60, 80, 100].map((percent, index) => (
                  <div key={index} className="relative">
                    <div className="border-t border-neutral-200/50 dark:border-neutral-700/50" />
                    <span className="absolute -left-14 -top-2 text-xs font-medium 
                      text-neutral-500 dark:text-neutral-500">
                      ${Math.round((maxValue * percent) / 100).toLocaleString()}
                    </span>
                  </div>
                ))}
              </div>

              {/* Barres du graphique */}
              <div className="absolute inset-0 flex items-end justify-between px-2 sm:px-4 pb-10 gap-2 sm:gap-4">
                {monthlyData.map((data, index) => {
                  const barHeight = (data.revenue / maxValue) * 100;
                  const targetHeight = (data.target / maxValue) * 100;
                  const animationDelay = index * 100;

                  return (
                    <div
                      key={data.month}
                      className="flex flex-col items-center flex-1 group"
                      onMouseEnter={() => setHoveredBar(index)}
                      onMouseLeave={() => setHoveredBar(null)}
                    >
                      <div className="relative w-full flex flex-col items-center h-full justify-end">
                        {/* Barre d'objectif */}
                        <div
                          className={`absolute w-3/4 h-1.5 bg-gradient-to-r from-accent-500 to-accent-400 
                            rounded-full opacity-60 group-hover:opacity-100 transition-all duration-500
                            ${hoveredBar === index ? 'scale-110' : ''}`}
                          style={{ 
                            bottom: `${targetHeight}%`,
                            transitionDelay: `${animationDelay}ms`
                          }}
                        />

                        {/* Barre principale */}
                        <div
                          className={`relative w-4/5 rounded-t-xl transition-all duration-700 ease-out
                            ${getBarColor(data.growth)} bg-gradient-to-t
                            ${hoveredBar === index ? 'scale-105 w-5/6 shadow-lg' : ''}
                            cursor-pointer group/bar`}
                          style={{ 
                            height: `${barHeight}%`,
                            transitionDelay: `${animationDelay}ms`
                          }}
                        >
                          {/* Effet de brillance */}
                          <div className="absolute inset-0 bg-gradient-to-b from-white/30 to-transparent 
                            rounded-t-xl" />

                          {/* Animation de remplissage */}
                          <div className="absolute inset-0 bg-gradient-to-t from-white/10 to-transparent 
                            -translate-y-full group-hover/bar:translate-y-0 transition-transform duration-500" />

                          {/* Tooltip */}
                          <div className={`absolute -top-20 left-1/2 transform -translate-x-1/2 
                            bg-neutral-900 dark:bg-neutral-800 text-white text-sm py-2 px-3 
                            rounded-xl shadow-2xl opacity-0 group-hover/bar:opacity-100 
                            transition-all duration-300 whitespace-nowrap z-20 border 
                            border-neutral-700 pointer-events-none
                            ${hoveredBar === index ? 'scale-100' : 'scale-90'}`}>
                            <div className="font-semibold mb-1">{data.month}</div>
                            <div className="flex items-center gap-2">
                              <DollarSign className="h-3 w-3" />
                              <span>Revenu: ${data.revenue.toLocaleString()}</span>
                            </div>
                            <div className="flex items-center gap-2 mt-1">
                              <Target className="h-3 w-3 text-accent-400" />
                              <span>Objectif: ${data.target.toLocaleString()}</span>
                            </div>
                            <div className={`flex items-center gap-2 mt-1 ${getGrowthColor(data.growth)}`}>
                              {data.growth >= 0 ? (
                                <TrendingUp className="h-3 w-3" />
                              ) : (
                                <TrendingDown className="h-3 w-3" />
                              )}
                              <span>Croissance: {data.growth}%</span>
                            </div>
                            <div className="absolute -bottom-2 left-1/2 transform -translate-x-1/2 
                              w-4 h-4 bg-neutral-900 dark:bg-neutral-800 rotate-45 border-r 
                              border-b border-neutral-700" />
                          </div>
                        </div>

                        {/* Indicateur de croissance */}
                        <div className={`mt-2 px-2 py-1 rounded-lg text-xs font-bold 
                          ${getGrowthColor(data.growth)} bg-white/50 dark:bg-neutral-800/50 
                          backdrop-blur-sm border border-neutral-200/50 dark:border-neutral-700/50
                          transition-all duration-500 ${hoveredBar === index ? 'scale-110' : ''}`}
                          style={{ transitionDelay: `${animationDelay + 100}ms` }}
                        >
                          {data.growth >= 0 ? '+' : ''}{data.growth}%
                        </div>
                      </div>

                      {/* Étiquette du mois */}
                      <span className="mt-3 text-sm font-semibold text-neutral-700 dark:text-neutral-300">
                        {data.month}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Statistiques détaillées */}
            <div className="mt-10 pt-8 border-t border-neutral-200/50 dark:border-neutral-700/50">
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {[
                  {
                    label: 'Revenu total',
                    value: `$${totalRevenue.toLocaleString()}`,
                    change: '+18.2%',
                    icon: DollarSign,
                    color: 'text-primary-600 dark:text-primary-400',
                    bg: 'bg-primary-500/10 dark:bg-primary-500/20'
                  },
                  {
                    label: 'Croissance moyenne',
                    value: `${averageGrowth}%`,
                    change: '+5.3%',
                    icon: TrendingUp,
                    color: 'text-emerald-600 dark:text-emerald-400',
                    bg: 'bg-emerald-500/10 dark:bg-emerald-500/20'
