                  {
                    label: 'Croissance max',
                    value: `${highestGrowth}%`,
                    change: 'Record',
                    icon: Sparkles,
                    color: 'text-amber-600 dark:text-amber-400',
                    bg: 'bg-amber-500/10 dark:bg-amber-500/20'
                  }
                ].map((stat, index) => {
                  const Icon = stat.icon;
                  return (
                    <div
                      key={index}
                      className="bg-white/50 dark:bg-neutral-800/50 backdrop-blur-sm 
